SELECT COALESCE(balance, 0)
FROM wallet_tbl
WHERE wallet_id = #{walletId}

mapper.update:
UPDATE wallet_tbl
SET balance = balance - #{amount}
WHERE wallet_id = #{walletId} AND balance >= #{amount}

UPDATE wallet_tbl
SET balance = balance + #{amount}
WHERE wallet_id = #{walletId}

UPDATE account_dummy_tbl
